def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for moving, target in ((4, 7), (8, 1)):
            sources = [c for c, v in enumerate(row) if v == moving]
            targets = [c for c, v in enumerate(row) if v == target]
            if not targets:
                continue
            for c in sources:
                out[r][c] = 0
                dest = min(targets, key=lambda t: abs(t-c))
                out[r][dest + (1 if c > dest else -1)] = moving
    return out

